    private func labeledExtract(
        suite: Data,
        salt: Data,
        label: String,
        inputKeyMaterial: Data
    ) -> Data {
        hkdfExtract(
            salt: salt,
            inputKeyMaterial: Data("HPKE-v1".utf8) + suite + Data(label.utf8) + inputKeyMaterial
        )
    }

    private func labeledExpand(
        suite: Data,
        pseudorandomKey: Data,
        label: String,
        info: Data,
        length: Int
    ) -> Data {
        hkdfExpand(
            pseudorandomKey: pseudorandomKey,
            info: i2osp(length, length: 2) + Data("HPKE-v1".utf8) + suite +
                Data(label.utf8) + info,
            length: length
        )
    }

    private func hkdfExtract(salt: Data, inputKeyMaterial: Data) -> Data {
        let key = SymmetricKey(data: salt.isEmpty ? Data(repeating: 0, count: 32) : salt)
        return Data(HMAC<SHA256>.authenticationCode(for: inputKeyMaterial, using: key))
    }

    private func hkdfExpand(
        pseudorandomKey: Data,
        info: Data,
        length: Int
    ) -> Data {
        var output = Data()
        var previous = Data()
        var counter: UInt8 = 1
        while output.count < length {
            previous = Data(
                HMAC<SHA256>.authenticationCode(
                    for: previous + info + Data([counter]),
                    using: SymmetricKey(data: pseudorandomKey)
                )
            )
            output.append(previous)
            counter += 1
        }
        return output.prefix(length)
    }

    private func i2osp(_ value: Int, length: Int) -> Data {
        Data((0 ..< length).map { index in
            UInt8((value >> (8 * (length - index - 1))) & 0xff)
        })
    }

    private func aesGcmSeal(
        key: Data,
        nonce: Data,
        aad: Data,
        plaintext: Data
    ) throws -> Data {
        let sealed = try AES.GCM.seal(
            plaintext,
            using: SymmetricKey(data: key),
            nonce: try AES.GCM.Nonce(data: nonce),
            authenticating: aad
        )
        return sealed.ciphertext + sealed.tag
    }

